import { gql, useSubscription } from '@apollo/client';

const ON_MESSAGE_ADDED = gql`
  subscription OnMessageAdded($channelId: ID!) {
    messageAdded(channelId: $channelId) {
      id
      content
      author { username }
      createdAt
    }
  }
`;

function LiveChat({ channelId }) {
  const { data, loading } = useSubscription(ON_MESSAGE_ADDED, {
    variables: { channelId },
  });

  if (loading) return <p>Waiting for messages...</p>;

  return (
    <div className="chat-message">
      <strong>{data.messageAdded.author.username}</strong>
      <p>{data.messageAdded.content}</p>
    </div>
  );
}
